-- Complete Customer Account Management System. Add this migration to a new Supabase project.
create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','MANAGER','EMPLOYEE');
create type public.record_status as enum ('ACTIF','ARCHIVE');
create type public.operation_status as enum ('BROUILLON','CONFIRMEE','ANNULEE');
create type public.payment_status as enum ('PENDING','PAID','REJECTED','CANCELLED');
create type public.document_status as enum ('BROUILLON','EMIS','ANNULE');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.app_role not null default 'EMPLOYEE', is_active boolean not null default true, display_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reference_counters (prefix text primary key check(prefix ~ '^[A-Z]{2,4}$'), last_value bigint not null default 0);
create table public.categories (id uuid primary key default gen_random_uuid(),reference text unique not null,name text not null check(char_length(trim(name))>0),description text,status public.record_status not null default 'ACTIF',archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(),reference text unique not null,name text not null check(char_length(trim(name))>0),city text,phone text,email text,address text,opening_balance numeric(14,2) not null default 0,status public.record_status not null default 'ACTIF',notes text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(),reference text unique not null,name text not null check(char_length(trim(name))>0),description text,category_id uuid references public.categories(id) on delete set null,unit text not null check(unit in('PCE','ML','M2','M3','KG','L','CARTON','LOT')),status public.record_status not null default 'ACTIF',notes text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.client_product_prices (id uuid primary key default gen_random_uuid(),reference text unique not null,client_id uuid not null references public.clients(id),product_id uuid not null references public.products(id),price numeric(14,2) not null check(price>=0),currency char(3) not null default 'MAD' check(currency='MAD'),unit text not null,effective_from date not null,effective_until date,status public.record_status not null default 'ACTIF',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(effective_until is null or effective_until>=effective_from));
create table public.operations (id uuid primary key default gen_random_uuid(),reference text unique not null,client_id uuid not null references public.clients(id),operation_date date not null default current_date,operation_type text not null default 'VENTE' check(operation_type='VENTE'),description text,total_amount numeric(14,2) not null default 0 check(total_amount>=0),status public.operation_status not null default 'BROUILLON',notes text,idempotency_key uuid unique not null default gen_random_uuid(),confirmed_at timestamptz,cancelled_at timestamptz,cancellation_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.operation_details (id uuid primary key default gen_random_uuid(),operation_id uuid not null references public.operations(id),product_id uuid not null references public.products(id),pricing_id uuid references public.client_product_prices(id),product_reference_snapshot text not null,product_name_snapshot text not null,quantity numeric(14,3) not null check(quantity>0),length_cm numeric(14,2),width_cm numeric(14,2),unit text not null,unit_price numeric(14,2) not null check(unit_price>=0),calculated_surface numeric(14,4),line_total numeric(14,2) not null check(line_total>=0),color text,color_name text,notes text);
create table public.payments (id uuid primary key default gen_random_uuid(),reference text unique not null,client_id uuid not null references public.clients(id),operation_id uuid references public.operations(id),payment_date date not null default current_date,amount numeric(14,2) not null check(amount>0),payment_method text not null check(payment_method in('ESPECES','CHEQUE','VIREMENT','CARTE','AUTRE')),due_date date,payment_status public.payment_status not null default 'PENDING',reference_number text,notes text,paid_at timestamptz,cancelled_at timestamptz,cancellation_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(due_date is null or due_date>=payment_date));
create table public.documents (id uuid primary key default gen_random_uuid(),reference text unique not null,document_type text not null check(document_type in('FACTURE','BON_LIVRAISON','RECU','RELEVE_COMPTE')),source_entity_type text,source_entity_id uuid,client_id uuid not null references public.clients(id),document_date date not null default current_date,status public.document_status not null default 'BROUILLON',snapshot_data jsonb not null default '{}'::jsonb,storage_path text,created_by uuid references auth.users(id),issued_by uuid references auth.users(id),issued_at timestamptz,cancelled_by uuid references auth.users(id),cancelled_at timestamptz,cancellation_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_history (id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid not null,action_type text not null,previous_data jsonb,new_data jsonb,performed_at timestamptz not null default now(),performed_by uuid references auth.users(id));

create index clients_name_idx on public.clients(status,name); create index products_name_idx on public.products(status,name); create index prices_lookup_idx on public.client_product_prices(client_id,product_id,effective_from desc) where status='ACTIF'; create index operations_client_date_idx on public.operations(client_id,operation_date desc); create index payments_client_date_idx on public.payments(client_id,payment_date desc); create index audit_entity_idx on public.audit_history(entity_type,entity_id,performed_at desc);
create or replace function public.next_reference(prefix_value text) returns text language plpgsql security definer set search_path=public as $$ declare n bigint; begin insert into public.reference_counters(prefix,last_value) values(prefix_value,1) on conflict(prefix) do update set last_value=public.reference_counters.last_value+1 returning last_value into n; return prefix_value||'-'||lpad(n::text,6,'0'); end $$;
create or replace function public.assign_ref() returns trigger language plpgsql as $$ begin if new.reference is null or btrim(new.reference)='' then new.reference:=public.next_reference(tg_argv[0]); end if; if tg_op='UPDATE' then new.updated_at:=now();end if;return new;end $$;
create or replace function public.assign_document_ref() returns trigger language plpgsql as $$ begin if new.reference is null or btrim(new.reference)='' then new.reference:=public.next_reference(case new.document_type when 'FACTURE' then 'FAC' when 'BON_LIVRAISON' then 'BL' when 'RECU' then 'REC' else 'RCL' end);end if;if tg_op='UPDATE' then new.updated_at:=now();end if;return new;end $$;
create or replace function public.validate_price() returns trigger language plpgsql as $$ begin if not exists(select 1 from public.products where id=new.product_id and unit=new.unit) then raise exception 'Unité tarifaire incompatible avec le produit';end if;if exists(select 1 from public.client_product_prices p where p.client_id=new.client_id and p.product_id=new.product_id and p.status='ACTIF' and p.id<>coalesce(new.id,gen_random_uuid()) and daterange(p.effective_from,coalesce(p.effective_until,'infinity'::date),'[]')&&daterange(new.effective_from,coalesce(new.effective_until,'infinity'::date),'[]')) then raise exception 'Chevauchement de périodes tarifaires interdit';end if;return new;end $$;
create or replace function public.validate_line() returns trigger language plpgsql as $$ declare s numeric(14,4);begin if new.unit='M2' then s:=round(new.length_cm*new.width_cm*new.quantity/10000,4);if new.calculated_surface<>s or new.line_total<>round(s*new.unit_price,2) then raise exception 'Calcul M² invalide';end if;elsif new.line_total<>round(new.quantity*new.unit_price,2) then raise exception 'Total de ligne invalide';end if;return new;end $$;
create or replace function public.customer_ledger() returns table(client_id uuid,entry_date date,reference text,description text,debit numeric,credit numeric) language sql stable as $$ select id,created_at::date,reference,'Solde d''ouverture',greatest(opening_balance,0),greatest(-opening_balance,0) from public.clients union all select client_id,operation_date,reference,coalesce(description,'Vente confirmée'),total_amount,0 from public.operations where status='CONFIRMEE' union all select client_id,payment_date,reference,'Paiement encaissé',0,amount from public.payments where payment_status='PAID' $$;
create view public.customer_balances with (security_invoker = true) as select client_id,coalesce(sum(debit-credit),0)::numeric(14,2) balance from public.customer_ledger() group by client_id;
create trigger client_ref before insert or update on public.clients for each row execute procedure public.assign_ref('CL'); create trigger category_ref before insert or update on public.categories for each row execute procedure public.assign_ref('CAT'); create trigger product_ref before insert or update on public.products for each row execute procedure public.assign_ref('PR'); create trigger price_ref before insert or update on public.client_product_prices for each row execute procedure public.assign_ref('PX'); create trigger operation_ref before insert or update on public.operations for each row execute procedure public.assign_ref('OP'); create trigger payment_ref before insert or update on public.payments for each row execute procedure public.assign_ref('PA'); create trigger document_ref before insert or update on public.documents for each row execute procedure public.assign_document_ref(); create trigger pricing_valid before insert or update on public.client_product_prices for each row execute procedure public.validate_price(); create trigger line_valid before insert or update on public.operation_details for each row execute procedure public.validate_line();

alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.clients enable row level security; alter table public.products enable row level security; alter table public.client_product_prices enable row level security; alter table public.operations enable row level security; alter table public.operation_details enable row level security; alter table public.payments enable row level security; alter table public.documents enable row level security; alter table public.audit_history enable row level security;
create or replace function public.is_active_role(allowed public.app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and is_active and role=any(allowed)) $$;
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.email)) on conflict(id) do nothing; return new; end $$;
create trigger new_auth_profile after insert on auth.users for each row execute procedure public.create_profile();
create policy "profile self or admin read" on public.profiles for select to authenticated using(id=auth.uid() or public.is_active_role(array['ADMIN']::public.app_role[]));
create policy "profile admin write" on public.profiles for all to authenticated using(public.is_active_role(array['ADMIN']::public.app_role[])) with check(public.is_active_role(array['ADMIN']::public.app_role[]));
create policy "staff read categories" on public.categories for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write categories" on public.categories for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read clients" on public.clients for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write clients" on public.clients for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read products" on public.products for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write products" on public.products for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read prices" on public.client_product_prices for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write prices" on public.client_product_prices for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read operations" on public.operations for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write operations" on public.operations for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read lines" on public.operation_details for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write lines" on public.operation_details for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read payments" on public.payments for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write payments" on public.payments for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read documents" on public.documents for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write documents" on public.documents for all to authenticated using(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[])) with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
create policy "staff read audit" on public.audit_history for select to authenticated using(public.is_active_role(array['ADMIN','MANAGER','EMPLOYEE']::public.app_role[])); create policy "manager write audit" on public.audit_history for insert to authenticated with check(public.is_active_role(array['ADMIN','MANAGER']::public.app_role[]));
revoke execute on function public.next_reference(text) from public;
revoke execute on function public.is_active_role(public.app_role[]) from public;
grant execute on function public.next_reference(text), public.is_active_role(public.app_role[]) to authenticated;
grant select,insert,update,delete on public.categories,public.clients,public.products,public.client_product_prices,public.operations,public.operation_details,public.payments,public.documents,public.audit_history to authenticated;
grant select,update on public.profiles to authenticated;
grant select on public.customer_balances to authenticated;
